def N(text,answer,explanation):return dict(type='number',text=text,answer=answer,explanation=explanation,options=[])
def C(text,options,answer,explanation):return dict(type='choice',text=text,options=options,answer=answer,explanation=explanation)
def F(value):return str(value.numerator) if value.denominator==1 else f'{value.numerator}/{value.denominator}'

