def authored_minis(topics):
    result=[]
    for unit,titles in enumerate(topics,1):
        for topic,title in enumerate(titles,1):
            id=f'{unit}-{topic}'
            if id=='1-1':continue
            questions=[]
            for i in range(3):
                for level,q in enumerate(lesson(id,i),1):
                    if i and (id,level) in VARIANTS:q=dict(VARIANTS[(id,level)][i-1])
                    q.update(id=f'{id}-{level}-{i+1}',level=level,hint=f'{title}의 뜻과 조건을 먼저 확인하고, 필요한 식을 한 줄씩 써 보세요.')
                    if q['type']=='choice':
                        order=list(range(len(q['options'])));Random(q['id']).shuffle(order)
                        q['options']=[q['options'][j] for j in order];q['answer']=order.index(q['answer']-1)+1
                    questions.append(q)
            questions.sort(key=lambda q:(q['level'],q['id']))
            # The extension is an additional fourth example of the final skill.
            bonus=lesson(id,3)[-1] if unit not in (8,) or id not in ('8-3',) else N('한 외각이 24도인 정다각형은 몇 각형인가요?',15,'360÷24=15이므로 정15각형입니다.')
            extensions={'6-3':N('직육면체의 한 모서리와 만나는 모서리 수와 꼬인 모서리 수의 합은?',8,'만나는 4개와 꼬인 4개를 합하면 8개입니다.'),'6-4':N('평행선의 같은 쪽 두 내각이 (2x+20)도와 (x+40)도입니다. x는?',40,'두 각의 합 180도에서 3x+60=180이므로 x=40입니다.'),'8-4':N('같은 원에서 호 길이가 3:2인 두 부채꼴이 있습니다. 작은 중심각이 60도이면 큰 중심각은?',90,'60×3/2=90도입니다.'),'9-5':N('반지름 3인 구의 겉넓이를 Aπ, 부피를 Bπ라 할 때 A+B는?',72,'A=36, B=36이므로 합은 72입니다.')}
            bonus=extensions.get(id,bonus)
            bonus.update(id=f'{id}-bonus',level=6,hint='기본 탐험의 마지막 원리를 다른 수에 적용해 보세요.')
            scene,mission=SCENES[unit-1]
            result.append(dict(id=id,unit=unit,title=title,story=f'{scene} · {title} 연구실',intro=f'{mission} 이번 임무는 {title}입니다. 관찰·연습·구별·수리·적용의 다섯 방을 천천히 해결하세요.',levels=['개념 관찰','기초 연습','조건 구별','오류 수리','생활 속 적용'],questions=questions+[bonus]))
    return result
